// FrameCodec encodes outbound payloads and decodes inbound chunks.
// The decoder is stateful so it can buffer across WebSocket-message
// boundaries — PVE termproxy frames don't always align with single
// WebSocket frames.
type FrameCodec interface {
	// Encode serializes a payload for the wire. Type asserted by the
	// caller (string for terminal, []byte for VNC).
	Encode(payload interface{}) (interface{}, error)
	// Decode appends decoded payloads from chunk into out and returns
	// the new slice.
	Decode(chunk []byte, out [][]byte) [][]byte
}

const PvePingFrame = "2"

// TextFrameCodec implements PVE termproxy framing.
type TextFrameCodec struct {
	pending []byte
}

func NewTextFrameCodec() *TextFrameCodec { return &TextFrameCodec{} }

func (c *TextFrameCodec) Encode(payload interface{}) (interface{}, error) {
	switch v := payload.(type) {
	case string:
		return fmt.Sprintf("0:%d:%s\n", len(v), v), nil
	case []byte:
		return fmt.Sprintf("0:%d:%s\n", len(v), string(v)), nil
	}
	return nil, fmt.Errorf("unsupported terminal payload type %T", payload)
}

// EncodeResize produces the wire frame for a terminal-resize event.
func (c *TextFrameCodec) EncodeResize(cols, rows int) string {
	return fmt.Sprintf("1:%d:%d:", cols, rows)
}

// Decode passes raw inbound bytes through unchanged. PVE termproxy is
// asymmetric: client→server is framed (`0:LEN:DATA`), server→client
// is the underlying TTY output without framing. Surface every chunk
// to the caller verbatim.
func (c *TextFrameCodec) Decode(chunk []byte, out [][]byte) [][]byte {
	if len(chunk) == 0 {
		return out
	}
	frame := make([]byte, len(chunk))
	copy(frame, chunk)
	return append(out, frame)
}

// BinaryFrameCodec is a pass-through codec for raw RFB bytes.
type BinaryFrameCodec struct{}

func NewBinaryFrameCodec() *BinaryFrameCodec { return &BinaryFrameCodec{} }

func (BinaryFrameCodec) Encode(payload interface{}) (interface{}, error) {
	switch v := payload.(type) {
	case []byte:
		return v, nil
	case string:
		return []byte(v), nil
	}
	return nil, fmt.Errorf("unsupported VNC payload type %T", payload)
}

func (BinaryFrameCodec) Decode(chunk []byte, out [][]byte) [][]byte {
	if len(chunk) == 0 {
		return out
	}
	frame := make([]byte, len(chunk))
	copy(frame, chunk)
	return append(out, frame)
}

