func (b *baseTermproxyIssuer) Issue(ctx context.Context, client *APIClient, target Target) (ConsoleTicket, string, error) {
	resp, err := b.call(ctx, client, target)
	if err != nil {
		return ConsoleTicket{}, "", err
	}
	t, err := ticketFromInterface(resp.GetData())
	return t, b.pathPrefix(target), err
}

