func ticketFromInterface(v interface{}) (ConsoleTicket, error) {
	m, ok := v.(map[string]interface{})
	if !ok {
		return ConsoleTicket{}, fmt.Errorf("unexpected ticket payload type %T", v)
	}
	t := ConsoleTicket{}
	if s, ok := m["ticket"].(string); ok {
		t.Ticket = s
	}
	if s, ok := m["user"].(string); ok {
		t.User = s
	}
	if s, ok := m["upid"].(string); ok {
		t.Upid = s
	}
	if s, ok := m["cert"].(string); ok {
		t.Cert = s
	}
	switch p := m["port"].(type) {
	case float64:
		t.Port = int(p)
	case int:
		t.Port = p
	case int32:
		t.Port = int(p)
	case string:
		parsed, err := strconv.Atoi(p)
		if err != nil {
			return t, fmt.Errorf("port %q is not numeric: %w", p, err)
		}
		t.Port = parsed
	}
	if t.Ticket == "" || t.Port == 0 {
		return t, fmt.Errorf("ticket payload missing required fields (ticket=%q port=%d)", t.Ticket, t.Port)
	}
	return t, nil
}

