// AuthAttacher contributes auth headers to the upgrade request.
type AuthAttacher interface {
	Headers(cfg *Configuration) http.Header
}

// CompositeAuthAttacher merges headers from multiple strategies.
type CompositeAuthAttacher struct{ attachers []AuthAttacher }

func NewCompositeAuthAttacher(attachers ...AuthAttacher) *CompositeAuthAttacher {
	return &CompositeAuthAttacher{attachers: attachers}
}

func (c *CompositeAuthAttacher) Headers(cfg *Configuration) http.Header {
	merged := http.Header{}
	for _, a := range c.attachers {
		for k, vs := range a.Headers(cfg) {
			for _, v := range vs {
				merged.Add(k, v)
			}
		}
	}
	return merged
}

type defaultHeaderAttacher struct{ key string }

func (a defaultHeaderAttacher) Headers(cfg *Configuration) http.Header {
	h := http.Header{}
	if cfg != nil && cfg.DefaultHeader != nil {
		if v, ok := cfg.DefaultHeader[a.key]; ok && v != "" {
			h.Set(a.key, v)
		}
	}
	return h
}

var defaultAuth AuthAttacher = NewCompositeAuthAttacher(
	defaultHeaderAttacher{key: "Authorization"},
	defaultHeaderAttacher{key: "Cookie"},
)

