// WebSocketTransport opens an upgraded WebSocket connection.
type WebSocketTransport interface {
	Open(ctx context.Context, url string, headers http.Header) (*gws.Conn, error)
}

// GorillaTransport is the default WebSocketTransport, backed by
// gorilla/websocket. The Dialer field is exported so callers can supply
// a custom *gws.Dialer (e.g. with TLSClientConfig.InsecureSkipVerify
// for self-signed PVE hosts, or a custom NetDialContext for proxies).
// Zero value uses gws.DefaultDialer.
type GorillaTransport struct {
	Dialer *gws.Dialer
}

func (g GorillaTransport) Open(ctx context.Context, target string, headers http.Header) (*gws.Conn, error) {
	d := g.Dialer
	if d == nil {
		d = gws.DefaultDialer
	}
	conn, _, err := d.DialContext(ctx, target, headers)
	if err != nil {
		return nil, fmt.Errorf("websocket upgrade failed: %w", err)
	}
	return conn, nil
}

// DefaultTransport is the package-level WebSocketTransport used by
// ConnectTerminal / ConnectVnc. Replace it (or its Dialer) before
// calling those helpers to inject custom TLS / proxy / timeout config.
var DefaultTransport WebSocketTransport = GorillaTransport{}

// ─────────────────────────────────────────────────────────────────────────────
// UrlBuilder
// ─────────────────────────────────────────────────────────────────────────────

func buildUpgradeURL(cfg *Configuration, basePath string, ticket ConsoleTicket) (string, error) {
	rawURL, err := cfg.ServerURLWithContext(context.Background(), "")
	if err != nil {
		return "", err
	}
	u, err := url.Parse(rawURL)
	if err != nil {
		return "", err
	}
	switch u.Scheme {
	case "https":
		u.Scheme = "wss"
	case "http":
		u.Scheme = "ws"
	}
	u.Path = strings.TrimRight(u.Path, "/") + basePath + "/vncwebsocket"
	q := u.Query()
	q.Set("port", strconv.Itoa(ticket.Port))
	q.Set("vncticket", ticket.Ticket)
	u.RawQuery = q.Encode()
	return u.String(), nil
}

// ─────────────────────────────────────────────────────────────────────────────
// Sessions
// ─────────────────────────────────────────────────────────────────────────────

const pingInterval = 30 * time.Second

type baseSession struct {
	conn   *gws.Conn
	mu     sync.Mutex
	closed bool
}

func (s *baseSession) Close() error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closed {
		return nil
	}
	s.closed = true
	return s.conn.Close()
}

// TerminalSession owns the lifecycle of a terminal WebSocket. Frames
// are decoded by an injected TextFrameCodec.
type TerminalSession struct {
	baseSession
	codec     *TextFrameCodec
	cancel    context.CancelFunc
	OnMessage func(text string)
	OnClose   func(err error)
}

func (s *TerminalSession) Send(text string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closed {
		return errors.New("session closed")
	}
	frame, err := s.codec.Encode(text)
	if err != nil {
		return err
	}
	return s.conn.WriteMessage(gws.TextMessage, []byte(frame.(string)))
}

func (s *TerminalSession) Resize(cols, rows int) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closed {
		return errors.New("session closed")
	}
	return s.conn.WriteMessage(gws.TextMessage, []byte(s.codec.EncodeResize(cols, rows)))
}

func (s *TerminalSession) Close() error {
	if s.cancel != nil {
		s.cancel()
	}
	return s.baseSession.Close()
}

func (s *TerminalSession) readLoop() {
	for {
		_, payload, err := s.conn.ReadMessage()
		if err != nil {
			if s.OnClose != nil {
				s.OnClose(err)
			}
			s.mu.Lock()
			s.closed = true
			s.mu.Unlock()
			return
		}
		decoded := s.codec.Decode(payload, nil)
		for _, msg := range decoded {
			if s.OnMessage != nil {
				s.OnMessage(string(msg))
			}
		}
	}
}

func (s *TerminalSession) pingLoop(ctx context.Context) {
	t := time.NewTicker(pingInterval)
	defer t.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-t.C:
			s.mu.Lock()
			if s.closed {
				s.mu.Unlock()
				return
			}
			err := s.conn.WriteMessage(gws.TextMessage, []byte(PvePingFrame))
			s.mu.Unlock()
			if err != nil {
				return
			}
		}
	}
}

// VncSession owns the lifecycle of a VNC WebSocket. Frames pass
// through a BinaryFrameCodec unchanged.
type VncSession struct {
	baseSession
	codec   *BinaryFrameCodec
	OnFrame func(data []byte)
	OnClose func(err error)
}

func (s *VncSession) Send(data []byte) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closed {
		return errors.New("session closed")
	}
	return s.conn.WriteMessage(gws.BinaryMessage, data)
}

func (s *VncSession) readLoop() {
	for {
		_, payload, err := s.conn.ReadMessage()
		if err != nil {
			if s.OnClose != nil {
				s.OnClose(err)
			}
			s.mu.Lock()
			s.closed = true
			s.mu.Unlock()
			return
		}
		if s.OnFrame != nil {
			s.OnFrame(payload)
		}
	}
}

// ─────────────────────────────────────────────────────────────────────────────
// ConsoleConnector (Template Method)
// ─────────────────────────────────────────────────────────────────────────────

type consoleConnector struct {
	issuers         map[TargetKind]TicketIssuer
	auth            AuthAttacher
	transport       WebSocketTransport
	needsInbandAuth bool
}

func (c *consoleConnector) connect(ctx context.Context, client *APIClient, target Target) (*gws.Conn, ConsoleTicket, error) {
	issuer, ok := c.issuers[target.Kind]
	if !ok {
		return nil, ConsoleTicket{}, fmt.Errorf("no issuer registered for target kind %d", target.Kind)
	}
	ticket, basePath, err := issuer.Issue(ctx, client, target)
	if err != nil {
		return nil, ConsoleTicket{}, err
	}
	url, err := buildUpgradeURL(client.cfg, basePath, ticket)
	if err != nil {
		return nil, ConsoleTicket{}, err
	}
	// Resolve the transport at connect-time so callers can mutate
	// `DefaultTransport` (e.g. to inject a custom dialer with
	// `TLSClientConfig.InsecureSkipVerify`) any time before the call,
	// not only before package init.
	transport := c.transport
	if transport == nil {
		transport = DefaultTransport
	}
	conn, err := transport.Open(ctx, url, c.auth.Headers(client.cfg))
	if err != nil {
		return nil, ConsoleTicket{}, err
	}
	// PVE termproxy expects `<user>:<vncticket>\n` as the very first
	// frame after the WS handshake. gorilla.Dialer.DialContext returns
	// after the upgrade is complete, so the connection is open here —
	// push the auth inline before handing the conn over.
	if c.needsInbandAuth {
		if err := conn.WriteMessage(gws.TextMessage, []byte(fmt.Sprintf("%s:%s\n", ticket.User, ticket.Ticket))); err != nil {
			conn.Close()
			return nil, ConsoleTicket{}, fmt.Errorf("send inband auth: %w", err)
		}
	}
	return conn, ticket, nil
}

// transport is left nil here so the connect-time resolution falls
// back to the package-level `DefaultTransport` — see consoleConnector.connect.
var defaultTerminalConnector = &consoleConnector{
	issuers:         terminalIssuers,
	auth:            defaultAuth,
	needsInbandAuth: true,
}

var defaultVncConnector = &consoleConnector{
	issuers: vncIssuers,
	auth:    defaultAuth,
}

// ─────────────────────────────────────────────────────────────────────────────
// Public API
// ─────────────────────────────────────────────────────────────────────────────

// ConnectTerminal opens a terminal session against a node, QEMU VM,
// or LXC container. Frames flow into the OnMessage / OnClose
// callbacks on a background goroutine.
func (c *APIClient) ConnectTerminal(ctx context.Context, target Target) (*TerminalSession, error) {
	conn, _, err := defaultTerminalConnector.connect(ctx, c, target)
	if err != nil {
		return nil, err
	}
	pingCtx, cancel := context.WithCancel(context.Background())
	session := &TerminalSession{
		baseSession: baseSession{conn: conn},
		codec:       NewTextFrameCodec(),
		cancel:      cancel,
	}
	go session.readLoop()
	go session.pingLoop(pingCtx)
	return session, nil
}

// ConnectVnc opens a VNC session against a node shell, QEMU VM, or
// LXC container. Frames flow into the OnFrame / OnClose callbacks on
// a background goroutine.
func (c *APIClient) ConnectVnc(ctx context.Context, target Target) (*VncSession, error) {
	conn, _, err := defaultVncConnector.connect(ctx, c, target)
	if err != nil {
		return nil, err
	}
	session := &VncSession{
		baseSession: baseSession{conn: conn},
		codec:       NewBinaryFrameCodec(),
	}
	go session.readLoop()
	return session, nil
}
